SELECT id, user_id, title, content, content_format, word_count, type, status, is_top, like_count, comment_count, view_count, images, create_time, update_time FROM post WHERE user_id = #{userId} AND is_deleted = 0
AND status = 0
AND status != 0
AND status = #{status}
ORDER BY create_time DESC LIMIT #{offset}, #{size}

SELECT p.id as post_id, p.user_id, p.title, p.content, p.content_format, p.word_count, p.type, p.status, p.is_top, p.like_count, p.comment_count, p.view_count, p.images, p.create_time, p.update_time, u.user_name, u.avatar FROM post p LEFT JOIN user u ON p.user_id = u.id WHERE p.id IN
#{postId}
AND p.is_deleted = 0 ORDER BY p.create_time DESC

